const fs = require("fs");
const base = "/Users/kristinarash/Library/Caches/sportsci-batch-99";
const inputs = JSON.parse(fs.readFileSync(base + "/inputs.json", "utf8"));
const arr = Array.isArray(inputs) ? inputs : (inputs.papers || inputs.items || Object.values(inputs));
const tax = JSON.parse(fs.readFileSync(base + "/taxonomy.json", "utf8"));
const ids = ["Q41","Q42","Q43","Q44","Q45","Q46","Q47","Q48"];
for (const id of ids) {
  const src = arr.find(p => p.id === id);
  const d = JSON.parse(fs.readFileSync(`${base}/drafts/${id}.json`, "utf8"));
  const problems = [];
  if (d.id !== id) problems.push("id mismatch");
  if (d.sourceFile !== src.sourceFile) problems.push("sourceFile mismatch");
  if (d.decision === "EXCLUDE") { if (!d.exclusionReason) problems.push("no exclusionReason"); }
  if (d.decision === "INCLUDE") {
    if (!tax.studyDesigns.includes(d.studyDesign)) problems.push("bad studyDesign");
    if (!tax.domains.includes(d.primaryDomain)) problems.push("bad primaryDomain");
    if (!d.domains.includes(d.primaryDomain)) problems.push("primary not in domains");
    d.domains.forEach(x => { if (!tax.domains.includes(x)) problems.push("bad domain " + x); });
    d.audiences.forEach(x => { if (!tax.audiences.includes(x)) problems.push("bad audience " + x); });
    d.sports.forEach(x => { if (!tax.sports.includes(x)) problems.push("bad sport " + x); });
    d.populations.forEach(x => { if (!tax.populations.includes(x)) problems.push("bad population " + x); });
    if (!d.paper.doi.startsWith("10.")) problems.push("doi prefix");
  }
  const txt = JSON.stringify(d);
  if (/—/.test(txt)) problems.push("em dash present");
  console.log(id, d.decision, d.studyDesign, "| year", d.paper && d.paper.year, "| problems:", problems.length ? problems.join("; ") : "none");
}
EOF
node helpers/g6/check.js

