const fs = require("fs");
const dir = "/Users/kristinarash/Library/Caches/sportsci-batch-99/drafts/";
function load(f) { return JSON.parse(fs.readFileSync(dir + f, "utf8")); }
function save(f, d) { fs.writeFileSync(dir + f, JSON.stringify(d, null, 1) + "\n"); }
function rep(s, a, b) {
  if (s.indexOf(a) < 0) throw new Error("not found: " + a.slice(0, 60));
  return s.replace(a, b);
}

// Q48: full limitations, authors' own practical wording
let d = load("Q48.json");
d.paper.limitations = "The fatigue analysis used five average-value and nine highest-value effect sizes, and 73% of CMJ variables were reported in only one or two studies. Acute studies (under three weeks) were excluded, and the authors say this may have influenced the results. Pooling across sports, ability and training status, and across force plates, position transducers and contact mats, may also have confounded the results. The authors could not determine whether the number of averaged trials changes sensitivity, and pooled participants were 80% male and 40% non-athletes. The highest and average comparison relies on separate pooled estimates, and the text reports no between-subgroup test statistic.";
d.paper.practicalImplications = "Use the average of CMJ trials performed without arm swing to track neuromuscular status, since average height was more sensitive than highest height in this review. Choose monitoring variables with a small-to-moderate CV and a moderate-to-large effect size, as the authors recommend, and treat fatigue signals with caution because the average-value fatigue evidence is limited.";
d.paper.athleteDev = "Use the average of several CMJ trials, without arm swing, to track fatigue and supercompensation, and prefer variables with a small-to-moderate CV and a moderate-to-large effect size. Jump height is simple to take from flight time, but the number of trials to average is not established and the average-value fatigue evidence is thin.";
save("Q48.json", d);

// Q42: reconcile counts as the source does
d = load("Q42.json");
d.paper.findings = rep(d.paper.findings,
  "18 used rolling averages, five used the exponentially weighted moving average (EWMA), and four compared both.",
  "Eighteen studies used rolling averages alone and four compared rolling averages with the exponentially weighted moving average (EWMA); the authors also refer to five EWMA studies, a count the text does not reconcile.");
save("Q42.json", d);

// Q44: state data rather than instructions; add elite level stated in text
d = load("Q44.json");
d.paper.tldr = rep(d.paper.tldr, "but peak power was too variable to use for monitoring.", "but peak power was too variable (CV 40 to 58%) to rely on for monitoring.");
d.paper.practicalImplications = rep(d.paper.practicalImplications,
  "Do not base decisions on peak power, whose variability was very high, and judge changes against the typical error and SWC, since most usefulness ratios were below 1.",
  "Peak power showed very high variability (CV 39.8 to 57.8%; ICC 0.11 to 0.30), so these data do not support using it for monitoring. Judge changes against the typical error and SWC, since most usefulness ratios were below 1.");
d.paper.athleteDev = rep(d.paper.athleteDev,
  "Do not use peak power as a monitoring metric, and interpret changes against the typical error before acting on them.",
  "Peak power's very high variability (CV 40 to 58%) means these data do not support it as a monitoring metric, and changes should be read against the typical error.");
d.populations = ["Male Athletes", "Healthy Athletes", "Youth / Adolescent", "Professional / Elite"];
save("Q44.json", d);
console.log("fixed");

